import{d as r,C as a,o as g,c as d,a3 as t,E as e,j as s,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第三十六章","description":"《正易心法》第三十六章——策数六八，八卦定数：八卦经画二十四、重之四十八，四十八为八卦定数；大衍五十、其用四十九、实用四十八；辨今筮者误用四十九之失，明揲法取余不取正。","frontmatter":{"title":"正易心法·第三十六章","description":"《正易心法》第三十六章——策数六八，八卦定数：八卦经画二十四、重之四十八，四十八为八卦定数；大衍五十、其用四十九、实用四十八；辨今筮者误用四十九之失，明揲法取余不取正。","category":"guide","aliases":["正易心法第三十六章","策数六八八卦定数","四十八为八卦定数"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-36.md","filePath":"yijing/zheng-yi-xin-fa/chapter-36.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-36.md"},x=r({...c,setup(u){const i=[{id:"z36-01",label:"一、策数六八",showLabel:!0,sentences:[["策数六八，八卦定数。卦数占卦，理之自然。"]],note:["策数是六乘八（四十八），这是八卦的定数。用卦的数来占卦，是事理的自然。（**本章是全书的筮法技术章**——第二十九章讲「384 与闰年」，本章讲「怎么在蓍草上把它操作出来」。**麻衣的落点始终如一：最宏大的道理，要落在最具体的操作上。**）"]},{id:"z36-02",label:"二、四十八之数",showLabel:!0,sentences:[["八卦",{text:"经画",glossary:"jinghua"},"二十四，重之则四十八，又每卦八变，六八四十八。则四十八者，",{text:"八卦定数",glossary:"baguaDingshu"},"也。"]],note:["八卦每卦经画三爻，共二十四画；重卦则四十八；又每卦八变，六乘八等于四十八。所以四十八是八卦的定数。（**本章最关键的数就是这个 48**——**它是「筮法的真正操作数」**。注意原文「684十八」当为「六八四十八」的传抄之误。）"]},{id:"z36-03",label:"三、五十与四十九",showLabel:!0,sentences:[["大衍之数五十者，",{text:"半百一进数",glossary:"banbaiYijinshu"},"也。其用四十九者，",{text:"体用全数",glossary:"tiyongQuanshu"},"也。五十除一者，无一也，易",{text:"无形埒",glossary:"wuxinglie"},"是也。四十九有卦一也者，有一也，《易》变为一是也。一不用者，数之宗本也，",{text:"可动",glossary:"kedong"},"也。用四十八者，取八数变以占诸卦也。一变为七，七变为九。此之谓也。"]],note:["（**三个核心数的层次**：**50＝大衍之数**（半百一进数）；**49＝体用全数**（挂一为体、48 为用）；**48＝真正参与演算的数**。**「五十除一者，无一也，易无形埒是也」**——五十去掉一，回到「无一」，即第四十章所说「无形无界」的状态；**「四十九有卦一也者，有一也」**——四十九中那个「卦一」，是「有一」。**注意末句「一不用者，数之宗本也，可动也」的「可动」二字与第三十五章「理自不动」相左**，是本章留下的待考之处：或谓宗本之体不动，而其「用」可以在场——存以备考。）"]},{id:"z36-04",label:"四、今筮者之误",showLabel:!0,sentences:[["今筮者于五十数，先置一于前，乃揲之以四十九。或先去其一，欲于四十九数中除一，而终合之。是二者皆全用四十九数，曾不知本卦之本数也。以致误置一于本卦数中，遂有",{text:"五与九之失",glossary:"wuyuJiu"},"也。"]],note:["（**两种错误筮法**：一是「先置一于前，乃揲之以四十九」——搁置一根，仍用四十九根演算；二是「先去其一……而终合之」——先去掉一根用四十八，最后又合并回来。**两者都全用四十九数**，不曾知道本卦的本数（四十八）。**麻衣的批评很细**：这不是「算错了」，而是「不知道本卦的本数」——**方法的错，不是结果的错。**）"]},{id:"z36-05",label:"五、取余不取正",showLabel:!0,sentences:[["且以揲之",{text:"寄数",glossary:"jishu"},"，但论其多少，而五与九，则无损益于多少之数。而于阴阳正数，亦自无碍。揲法不取其正数，而取其余数，盖从其简便也，简便，谓一见多少。若待视正数，则烦难矣。又多少之说，无所经见，知古人但以记数也。"]],note:["就着揲法的余数来说，只论多少；而五与九对多少之数并无损益，对阴阳正数也没有妨碍。揲法不取正数而取余数，是为了简便——简便，是说一眼就能看出多少；如果要看正数，就繁难了。而且「多少」的说法，经典中没有明文，可知古人只是用来记数。（**这一段是麻衣为自己的驳论「留后门」**：他承认 49 与 48 的差别**对结果没有影响**——**但差别仍然存在，它证明的是操作的错，不是结果的错。**）"]},{id:"z36-06",label:"六、大传之说",showLabel:!0,sentences:[["《大传》曰：“大衍之数五十，其用四十九。”谓大衍数本五十，而止用四十九，则其一己先除矣，更无五十全数。分而为二以象四，谓止于四十九数中分而为二也。挂一象三，挂为悬，谓之四十九数中悬挂其一而不用也。"]],note:["《大传》说「大衍之数五十，其用四十九」，意思是大衍数本来是五十，只用四十九，那个「一」已经先除去了，并没有五十的全数。「分而为二以象两」，是说在四十九数中分为两份。「挂一象三」，挂是悬挂，是说在四十九数中悬挂其一而不用。（**麻衣对经文的读法**：**「其一己先除」——五十之中先去掉一个，剩下的才是「四十九」。** 这与第三十五章「挂一不用」是同一件事的两种说法。）"]},{id:"z36-07",label:"七、三少三多与策数",showLabel:!0,sentences:[["筮法，一揲得五与四，四谓之",{text:"三少",glossary:"sanshao"},"。得九与八，八谓之",{text:"三多",glossary:"sanduo"},"。二揲，则五与九已矣。但得三个四，亦谓之三少。得三个八，亦谓之三多，方初得五与九也。而老阳之策三十六，老阴之策二十四，及次正得四与八也，而阴阳之策数如前。则是五九固无损益于多少数，而于阴阳之策正数亦自无伤也。"]],note:["（**三少三多的判法**：第一变余数得五或四，四称为「三少」；得九或八，八称为「三多」。第二、三变则不再出现五与九，只有四与八。**四爻的策数**：三少＝老阳，策三十六；三多＝老阴，策二十四；其余次正得四与八，策数为三十二（少阴）与二十八（少阳）。**「五九固无损益于多少数，而于阴阳之策正数亦自无伤」——麻衣仍是为自己的驳论划边界：** 用 49 还是 48，对结果无伤；有伤的是「不知本数」。）"]},{id:"z36-08",label:"八、四十八为正",showLabel:!0,sentences:[["因知四十八数而误用其九，断然而明矣。或者又谓揲法得",{text:"奇偶数",glossary:"jiouShu"},"。殊不知二揲则五与九已尽。所以观其余数，而不观其正数，特以从其简便也。"]],note:["（**「四十八数而误用其九」，断然而明**——这是本章的判断落点。**最后又驳一说「揲法得奇偶数」**：麻衣说殊不知第二揲时五与九已经用尽。**所以观余数而不观正数，只是为了简便**——从「简便」上说，取余数确实更省力。**这就是本章的分寸**：不是把古人一棍子打死，而是把「所以然」说清楚。）"]}],o=[{id:"jinghua",term:"经画",pinyin:"jīng huà",meaning:"单卦的爻画。八卦各三爻，8×3＝24 画。"},{id:"baguaDingshu",term:"八卦定数",pinyin:"bā guà dìng shù",meaning:"四十八。六爻×八卦＝48，是筮法的真正操作数。"},{id:"banbaiYijinshu",term:"半百一进数",pinyin:"bàn bǎi yī jìn shù",meaning:"五十是半百再进一之数（49＋1）。"},{id:"tiyongQuanshu",term:"体用全数",pinyin:"tǐ yòng quán shù",meaning:"四十九是体用合一的完整数（挂一为体，48 为用）。"},{id:"wuxinglie",term:"无形埒",pinyin:"wú xíng liè",meaning:"没有形体的边界。埒＝界墙。语本《列子》，指易的无形无界。"},{id:"kedong",term:"可动",pinyin:"kě dòng",meaning:"原文作「可动也」，与第三十五章「理自不动」看似相左。可理解为「宗本之体不动，而其用可以在场」，是麻衣留下的待考之处。"},{id:"wuyuJiu",term:"五与九之失",pinyin:"wǔ yǔ jiǔ zhī shī",meaning:"第一变余数应为五或九，麻衣指其为操作数错误（用了 49 而非 48）的证明。"},{id:"jishu",term:"寄数",pinyin:"jì shù",meaning:"每变搁置的余数，不参与下一变。"},{id:"sanshao",term:"三少",pinyin:"sān shǎo",meaning:"三次得少（余数小），少为阳——三少即老阳（变爻）。"},{id:"sanduo",term:"三多",pinyin:"sān duō",meaning:"三次得多（余数大），多为阴——三多即老阴（变爻）。"},{id:"jiouShu",term:"奇偶数",pinyin:"jī ǒu shù",meaning:"单数与双数。有人误以为揲法取奇偶，麻衣批评此说。"}];return(b,n)=>{const l=a("DaoTextReading"),p=a("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第三十六章" tabindex="-1">正易心法·第三十六章 <a class="header-anchor" href="#正易心法·第三十六章" aria-label="Permalink to &quot;正易心法·第三十六章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是全书的<strong>筮法技术章</strong>，核心命题：<strong>策数六八（48）是八卦定数，用卦数占卦是理之自然。</strong></p><p><strong>三个核心数的层次</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>50（大衍之数）＝ 半百一进数</span></span>
<span class="line"><span>  ↓ 五十除一 → 「无一也，易无形埒是也」</span></span>
<span class="line"><span>49（其用四十九）＝ 体用全数</span></span>
<span class="line"><span>  ↓ 「四十九有卦一也者，有一也」→ 再除「卦一」</span></span>
<span class="line"><span>48（八卦定数）＝ 真正参与演算的数</span></span></code></pre></div><p><strong>麻衣批评的两种错误筮法</strong>：</p><table tabindex="0"><thead><tr><th>错误</th><th>做法</th><th>问题</th></tr></thead><tbody><tr><td>一</td><td>先置一于前，揲之以四十九</td><td>实际操作数是 49</td></tr><tr><td>二</td><td>于四十九中除一，终合之</td><td>绕了一圈，仍用 49</td></tr></tbody></table><p><strong>正确做法</strong>：50 → 挂一（永久搁置）→ 49 → 卦一（在场不演算）→ <strong>48 为操作数</strong>。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「一变为七，七变为九」</strong>——这是第三十九章要解的悬案：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本章：「一变为七，七变为九。此之谓也。」（未给出出处）</span></span>
<span class="line"><span>第三十九章：引《冲虚经》——「易变而为一，一变而为七，七变而为九」</span></span>
<span class="line"><span>= 第三十九章解开了本章留下的引用悬案</span></span></code></pre></div><p><strong>「取余不取正」的理由</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>揲法取余数（不取正数），是为了「简便」——一见多少</span></span>
<span class="line"><span>若要看正数，则烦难矣</span></span>
<span class="line"><span>「多少」之说，经典无明文，可知古人只是用来记数</span></span></code></pre></div><p><strong>四爻的概率结构</strong>（阴阳之策）：</p><table tabindex="0"><thead><tr><th>爻</th><th>策数</th><th>概率</th></tr></thead><tbody><tr><td>老阳（三少）</td><td>36</td><td>3/16</td></tr><tr><td>少阴（二多一少）</td><td>32</td><td>5/16</td></tr><tr><td>少阳（二少一多）</td><td>28</td><td>7/16</td></tr><tr><td>老阴（三多）</td><td>24</td><td>1/16</td></tr></tbody></table><p><strong>变爻（老阳＋老阴）＝4/16＝1/4；不变爻＝3/4</strong>——<strong>宇宙的常态是「稳定」，变化是「例外」，但正是这个例外推动了卦的演化。</strong></p><p><strong>本章在全书中的位置</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>象（论卦象）：第一～二十章</span></span>
<span class="line"><span>数（论数理）：第二十一～三十五章</span></span>
<span class="line"><span>筮（论筮法）：第三十六章</span></span>
<span class="line"><span></span></span>
<span class="line"><span>象 → 数 → 筮 = 从原理到应用的完整链条</span></span></code></pre></div><p><strong>「义实落处」的最终形态</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第三十五章说「一不用」</span></span>
<span class="line"><span>第三十六章说：那根不用的蓍草，就是这样操作的</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 最宏大的道理，落在最具体的操作里</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把三个数分清：<strong>50（大衍）、49（其用）、48（操作数）</strong>；</li><li>再看两种错误筮法错在哪：<strong>都把 49 当成了操作数</strong>；</li><li>最后注意末段的「取余不取正」——<strong>这是麻衣为自己的驳论划出的边界。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>策数六八</strong>：48＝8×6，八卦定数。</li><li><strong>经画二十四</strong>：8×3＝24，重之则 48。</li><li><strong>三数层次</strong>：50 → 49 → 48。</li><li><strong>今筮者之误</strong>：误以 49 为操作数。</li><li><strong>取余不取正</strong>：为简便，且「多少」只是记数。</li><li><strong>三少三多</strong>：老阳 36、老阴 24。</li><li><strong>奇偶数之说</strong>：麻衣批评。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,25)),e(l,{colophon:"策数六八 · 五十与四十九 · 四十八为正 · 取余不取正",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十六章原文",sections:i,glossary:o}),n[1]||(n[1]=s("blockquote",null,[s("p",null,"注：本页依所据底本录入，用字随底本。原文数处疑有传抄讹误，依文义录如下：「684十八」当作「六八四十八」（已径改）、「方初得五与久也」之「久」当作「九」、「五豫九已尽」之「豫」当作「与」，此处说明而不尽改。又「一不用者，数之宗本也，可动也」之「可动」与第三十五章「理自不动」相左，当是麻衣另有层次之说（体不动而用可在场），存以备考。")],-1)),n[2]||(n[2]=s("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),s("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"策数六八",pinyin:["cè","shù"],meaning:"六乘八得四十八——8 卦 × 6 爻＝48，是筮法的真正操作数。"},{term:"五十 · 四十九 · 四十八",pinyin:["wǔ","shí"],meaning:"50＝大衍之数（半百一进数）；49＝体用全数；48＝八卦定数（实际操作数）。"},{term:"五与九之失",pinyin:["wǔ","yǔ"],meaning:"第一变余数为五或九。麻衣说这不是结果的错误，而是操作数错误的证明（用了 49 而非 48）。"},{term:"取余不取正",pinyin:["qǔ","yú"],meaning:"揲法只看余数（多少）而不看正数，是为简便；且「多少」之说本只用于记数。"},{term:"三少三多",pinyin:["sān","shǎo"],meaning:"三少为老阳（策 36），三多为老阴（策 24）。变爻占 1/4，不变爻占 3/4。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是<strong>筮法技术章</strong>，核心命题：<strong>策数六八（48）是八卦定数。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>50（大衍之数）→ 除一 → 49（体用全数）→ 除「卦一」→ 48（八卦定数＝操作数）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣批评两种错误筮法：都把 49 当成操作数</span></span></code></pre></div><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>为什么操作数必须是 48？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>48 = 6 × 8 = 八卦定数</span></span>
<span class="line"><span>= 筮法的操作数必须对应八卦的结构</span></span>
<span class="line"><span></span></span>
<span class="line"><span>八卦是以 8 为模的系统，六爻是以 6 为模的系统</span></span>
<span class="line"><span>48 = 8 × 6，是两个模的最小公倍数</span></span>
<span class="line"><span>= 能同时容纳卦和爻的最小完备数</span></span></code></pre></div><p><strong>「五与九之失」究竟是什么失？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用 49 操作时，第一变的余数可能出现 5 或 9——这本来没问题（多少判断不受影响）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>但麻衣的批评是：出现 5 或 9，说明你的操作数是 49，而不是正确的 48</span></span>
<span class="line"><span>= 5 和 9 的出现，不是结果的错误，而是操作的错误的证明</span></span>
<span class="line"><span></span></span>
<span class="line"><span>就像：答案碰巧对了，但解题过程是错的——麻衣批评的是过程，不是结果</span></span></code></pre></div><p><strong>「义实落处」的最终形态</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第三十五章：「一不用」</span></span>
<span class="line"><span>第三十六章：那根不用的蓍草，就是这样操作的</span></span>
<span class="line"><span>= 从太极（最抽象）到蓍草（最具体），麻衣走完了这条路</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>分清三个数：<strong>50、49、48</strong>；</li><li>看「五与九之失」的性质：<strong>它证明的是过程之错，不是结果之错</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>「卦数占卦，理之自然」——任何数都能映射到卦，这是发现对应还是制造对应？</strong> 我的看法：<strong>这个问题里，「发现」与「制造」的界线，取决于你是否承认「八卦是一个人的构造」。</strong> 如果承认，那**%8 的映射当然是「制造」的**；<strong>但麻衣的立场是「卦非人造」</strong>（第二十章「本之自然」），<strong>在他那里，%8 就是「发现」</strong>——<strong>因为卦本来就在万物之中（第十五章「一身一物便具八卦」）。</strong> 我不能替他证成这个前提，<strong>但可以指出：一旦接受「卦在万物之中」，「卦数占卦」就不再是人为投射，而是「读取」。</strong> 这正是全书最核心、也最需要被追问的一步。</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>策数是六乘八（四十八），这是八卦的定数。用卦的数来占卦，是事理的自然。</p><p>八卦每卦经画三爻，共二十四画；重卦则四十八；又每卦八变，六乘八等于四十八。所以四十八是八卦的定数。</p><p>大衍之数是五十，是半百再进一之数；其用四十九，是体用合一的完整数。五十除去一，是「无一」——易无形埒就是这个意思；四十九中有卦一，是「有一」——易变为一就是这个意思。一不用，是数的宗本（其说见下注）。用四十八，是取八卦之数来变占诸卦。「一变为七，七变为九」，说的就是这个。</p><p>现在的筮者，有的先把一根置于前，再用四十九根揲算；有的先去掉一根，想在四十九根中再除一根，最后再合并。这两种做法都全用四十九根，根本不知道本卦的本数（四十八），以至于误把那个「一」放进本卦的数中，于是产生了「五与九」的错误。</p><p>就着揲法的余数来说，只论多少；而五与九对多少之数并无损益，对阴阳正数也没有妨碍。揲法不取正数而取余数，是为了简便——简便，是说一眼就能看出多少；如果要看正数，就繁难了。而且「多少」的说法，经典中没有明文，可知古人只是用来记数。</p><p>《大传》说「大衍之数五十，其用四十九」，意思是大衍数本来是五十，只用四十九，那个「一」已经先除去了，并没有五十的全数。「分而为二以象两」，是说在四十九数中分为两份。「挂一象三」，挂是悬挂，是说在四十九数中悬挂其一而不用。</p><p>筮法：第一揲得五或四，四叫做「三少」；得九或八，八叫做「三多」。第二揲，则五与九已经用完。只要得三个四，也叫三少；得三个八，也叫三多。老阳之策三十六，老阴之策二十四。所以五与九确实对多少之数无损益，对阴阳策数也无妨。</p><p>由此可知，四十八数而误用其九，是断然清楚的错误。有人又说揲法得奇偶数，殊不知第二揲则五与九已经用尽。观余数而不观正数，只是为了简便。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第三十六章是全书最「手艺」的一章——<strong>它把第三十五章说的那根不用的蓍草，真正摆在了手上。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>三个数的层次</strong>——<strong>50（大衍）→ 49（其用）→ 48（定数）</strong>。麻衣说得很清楚：<strong>真正的操作数是 48，不是 49。</strong></li><li><strong>两种错误的筮法</strong>——一个「先置一于前」，一个「除一而终合之」。<strong>两种做法都绕过了那根「卦一」，结果都用了 49。</strong> 麻衣的批评很细：<strong>这不是「算错了」，是「不知道本卦的本数」。</strong></li><li><strong>「五与九之失」的性质</strong>——这一点最要紧：<strong>麻衣承认对结果没有影响</strong>（「无损益于多少之数」），<strong>他批评的是过程。</strong> 这很像数学课上老师说：<strong>答案对了，但方法不对。</strong> 麻衣的严格，在于<strong>方法本身要有落处</strong>。</li><li><strong>「取余不取正」</strong>——他给自己的驳论划了边界：<strong>从「简便」这个角度说，取余数确实更好。</strong> 但他也承认：<strong>「多少」之说本来只是记数的办法</strong>——<strong>这就是麻衣的分寸：他不是要把古人一棍子打死，是要把「所以然」说清楚。</strong></li><li><strong>「象→数→筮」的完整链条</strong>——全书到这里才真正收口：<strong>从卦象，到数理，到手上的蓍草。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>「卦数占卦，理之自然」——%8 的映射，是发现对应还是制造对应？</strong> 我的看法：<strong>取决于你是否承认「八卦是人的构造」。</strong> 如果承认，<strong>%8 当然是「制造」的</strong>；<strong>但麻衣的立场是「卦非人造」</strong>（第二十章「本之自然」），<strong>在他那里，%8 就是「发现」</strong>——因为<strong>卦本来就在万物之中</strong>（第十五章「一身一物便具八卦」）。我不能替他证成这个前提，<strong>但可以指出：一旦接受「卦在万物之中」，「卦数占卦」就不再是投射，而是读取。</strong> 这正是全书最核心、也最需要被追问的一步。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-34">第三十四章 · 便具五数</a> — 形之数（本章的筮法背景）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-35">第三十五章 · 大衍七七</a> — 「一不用」「理自不动」</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-38">第三十八章 · 生成感应</a> — 生数成数与感应之道</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-39">第三十九章</a> — 「一变为七，七变为九」的出处（解本章悬案）</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「大衍之数五十，其用四十有九」</li></ul>`,28))])}}});export{m as __pageData,x as default};
